  /* the same merge-patch algorithm the server uses, so a fixture patch is exactly what the server would send */
  function makePatch(a, b) {
    if (JSON.stringify(a) === JSON.stringify(b)) return null;
    if (a && b && typeof a === "object" && typeof b === "object" && !Array.isArray(a) && !Array.isArray(b)) {
      const p = {};
      for (const k of new Set([...Object.keys(a), ...Object.keys(b)])) {
        if (!(k in b)) p[k] = null; else if (!(k in a)) p[k] = clone(b[k]); else { const s = makePatch(a[k], b[k]); if (s !== null) p[k] = s; }
      }
      return Object.keys(p).length ? p : null;
    }
    return clone(b);
  }

