        for (let r = 0; r < 7; r++) { x.beginPath(); for (let i = 0; i <= 640; i += 8) { const y = 215 + r * 28 + Math.sin(i / 38 + r * 1.7) * 5; i ? x.lineTo(i, y) : x.moveTo(i, y); } x.stroke(); }
